from collect import group_by

def test_group_calls_independent():
    a = group_by([1, 2], lambda x: x % 2)
    b = group_by([10], lambda x: x % 2)
    assert a == {1: [1], 0: [2]}
    assert b == {0: [10]}

def test_group_empty():
    assert group_by([], lambda x: x) == {}


from recursion import reverse_rec

def test_reverse_single():
    assert reverse_rec("z") == "z"

def test_reverse_empty():
    assert reverse_rec("") == ""

def test_reverse_long():
    assert reverse_rec("abcdef") == "fedcba"
